.auth-login-back-link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.375rem;
  width: 100%;
  padding: 0.125rem 0;
  font-size: 0.75rem;
  font-weight: 550;
  line-height: 1.25;
