  font-size: 0.5625rem;
}
.auth-password-strength-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
}
.auth-password-strength-label {
  font-size: 0.5625rem;
  font-weight: 650;
