  border-color: var(--admin-primary, #0d5c3d) !important;
  background: var(--admin-primary, #0d5c3d) !important;
  color: #fff !important;
}
.auth-login-checkbox:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px color-mix(in oklch, var(--admin-primary, #0d5c3d) 28%, transparent);
}
.auth-login-checkbox [data-slot='checkbox-indicator'] svg {
  width: 0.75rem;
  height: 0.75rem;
  stroke-width: 3;
}
.auth-login-remember-label {
  font-size: 0.75rem !important;
  font-weight: 500 !important;
  cursor: pointer;
  color: #5f6f66;
}
.auth-login-submit {
  display: inline-flex !important;
  align-items: center;
  justify-content: center;
  gap: 0.4375rem;
