  background: #e2e8e4;
}
.auth-login-microsoft {
  height: 2.25rem !important;
  border-radius: 0.5rem !important;
  gap: 0.5rem;
  font-size: 0.8125rem !important;
}
.auth-login-panel-footer {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  margin-top: 0.875rem;
  padding-top: 0;
  border-top: 0;
  font-size: 0.6875rem;
  color: #8a978f;
}
.auth-login-panel-footer-secure {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  color: #5f7167;
