    transition: none !important;
  }
}
.dg-sidebar {
  --dg-sidebar-bg: oklch(0.32 0.085 155);
  --dg-sidebar-bg-deep: oklch(0.27 0.09 155);
  --dg-sidebar-border: oklch(0.4 0.095 155);
  --dg-sidebar-fg: oklch(0.95 0.02 155);
  --dg-sidebar-muted: oklch(0.74 0.06 155);
  --dg-sidebar-accent: oklch(0.38 0.1 155);
  --dg-sidebar-accent-fg: oklch(0.98 0.01 155);
  --dg-sidebar-active-bg: color-mix(in oklch, white 16%, var(--admin-primary));
  --dg-sidebar-active-fg: oklch(0.99 0.01 155);
  --dg-sidebar-active-bar: oklch(0.84 0.14 155);
  position: fixed;
  top: calc(2.75rem + 4px);
  left: 0;
  z-index: 30;
  height: calc(100vh - 2.75rem - 4px);
  border-right-style: var(--tw-border-style);
  border-right-width: 1px;
  --tw-backdrop-blur: blur(var(--blur-sm));
  -webkit-backdrop-filter: var(--tw-backdrop-blur,) var(--tw-backdrop-brightness,) var(--tw-backdrop-contrast,) var(--tw-backdrop-grayscale,) var(--tw-backdrop-hue-rotate,) var(--tw-backdrop-invert,) var(--tw-backdrop-opacity,) var(--tw-backdrop-saturate,) var(--tw-backdrop-sepia,);
  backdrop-filter: var(--tw-backdrop-blur,) var(--tw-backdrop-brightness,) var(--tw-backdrop-contrast,) var(--tw-backdrop-grayscale,) var(--tw-backdrop-hue-rotate,) var(--tw-backdrop-invert,) var(--tw-backdrop-opacity,) var(--tw-backdrop-saturate,) var(--tw-backdrop-sepia,);
  width: var(--dg-sidebar-width);
  border-right-color: var(--dg-sidebar-border);
