/* Navigation — barre de progression + skeleton de page */
.dg-nav-route-progress {
  position: fixed;
  top: calc(2.75rem + 4px);
  left: 0;
  right: 0;
  height: 3px;
  z-index: 60;
  background: color-mix(in oklch, var(--admin-primary) 18%, transparent);
  overflow: hidden;
}
