/* —— Mes demandes : panneau analytique ultra-pro —— */
.admin-appt-insight {
  display: flex;
  flex-direction: column;
  gap: 0.4375rem;
  min-width: 0;
}
.admin-appt-insight-kpis {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.375rem;
}
@media (width >= 40rem) {
  .admin-appt-insight-kpis {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}
.admin-appt-insight-kpi {
  position: relative;
  display: flex;
  align-items: center;
  gap: 0.4375rem;
  min-width: 0;
  padding: 0.4375rem 0.5625rem 0.4375rem 0.625rem;
  border: 1px solid color-mix(in oklch, #008d4c 12%, #dce3df);
  border-radius: 0.5rem;
  background: linear-gradient(180deg, #ffffff 0%, #f7fbf8 100%);
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.92) inset,
    0 6px 18px -14px rgba(15, 50, 35, 0.2);
  overflow: hidden;
}
.admin-appt-insight-kpi::before {
  content: '';
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 2px;
  background: color-mix(in oklch, #008d4c 55%, #94a89e);
}
.admin-appt-insight-kpi[data-tone='amber']::before {
  background: linear-gradient(180deg, #f59e0b 0%, #d97706 100%);
}
.admin-appt-insight-kpi[data-tone='green']::before {
  background: linear-gradient(180deg, #22c55e 0%, #008d4c 100%);
}
.admin-appt-insight-kpi[data-tone='rose']::before {
  background: linear-gradient(180deg, #f87171 0%, #dc2626 100%);
}
.admin-appt-insight-kpi[data-tone='teal']::before {
  background: linear-gradient(180deg, #2dd4bf 0%, #0d9488 100%);
}
.admin-appt-insight-kpi-icon {
  width: 1.625rem;
  height: 1.625rem;
  flex-shrink: 0;
  padding: 0.3125rem;
  border-radius: 0.4375rem;
  border: 1px solid color-mix(in oklch, #008d4c 14%, #dce3df);
  background: color-mix(in oklch, #008d4c 6%, white);
  color: #0a5c4c;
}
.admin-appt-insight-kpi[data-tone='amber'] .admin-appt-insight-kpi-icon {
  color: #b45309;
  border-color: color-mix(in oklch, #f59e0b 28%, #dce3df);
