  align-items: center;
  gap: 0.55rem;
  max-width: min(22rem, 70vw);
  min-height: 2.25rem;
  padding: 0.28rem 0.7rem 0.28rem 0.55rem;
  border-radius: 0.7rem;
  background: #fff;
  border: 1px solid #e4ece7;
  color: #1c2b3a;
  text-decoration: none;
}
.dg-cockpit-now-dot {
  width: 0.5rem;
  height: 0.5rem;
  flex: none;
  border-radius: 50%;
  background: #9aa8a0;
}
.dg-cockpit-now--ongoing {
  border-color: #b7e4cb;
  background: #f3faf6;
}
.dg-cockpit-now--ongoing .dg-cockpit-now-dot {
  background: #0f7a49;
  box-shadow: 0 0 0 3px rgba(15, 122, 73, 0.16);
}
.dg-cockpit-now--next {
  border-color: #c9dff5;
  background: #f4f8fc;
}
.dg-cockpit-now--next .dg-cockpit-now-dot { background: #1d6fbf; }
.dg-cockpit-now-copy {
  display: flex;
  min-width: 0;
  flex-direction: column;
  line-height: 1.15;
}
.dg-cockpit-now-copy small {
  color: #60717c;
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}
.dg-cockpit-now-copy strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 0.78rem;
}
.dg-cockpit-now time {
  flex: none;
  color: #60717c;
  font-size: 0.68rem;
  font-weight: 650;
}
.dg-cockpit-plan {
  padding: 0 0.9rem;
  background: #128a4e;
  color: #fff;
  box-shadow: 0 6px 14px rgba(18, 138, 78, 0.22);
}
.dg-cockpit-plan:hover {
  background: #0e7a4b;
}
.dg-cockpit-kpis {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.75rem;
}
.dg-cockpit-kpi {
  display: flex;
  align-items: center;
  gap: 0.7rem;
  min-height: 5.4rem;
  padding: 0.85rem 0.9rem;
  border-radius: 1rem;
  background: #fff;
  border: 1px solid #e7eeea;
  box-shadow: 0 8px 22px rgba(24, 48, 36, 0.04);
  text-decoration: none;
  color: inherit;
}
.dg-cockpit-kpi--inbox {
  background: linear-gradient(180deg, #fff8ef 0%, #fff 70%);
  border-color: #f3d7b0;
}
.dg-cockpit-kpi-icon {
  display: grid;
  place-items: center;
  width: 2.55rem;
  height: 2.55rem;
  flex: none;
  border-radius: 0.8rem;
}
.dg-cockpit-kpi-icon svg {
  width: 1.15rem;
  height: 1.15rem;
}
.dg-cockpit-kpi--rdv .dg-cockpit-kpi-icon {
  background: #e7f8ee;
  color: #14914d;
}
.dg-cockpit-kpi--reunion .dg-cockpit-kpi-icon,
.dg-cockpit-kpi--mission .dg-cockpit-kpi-icon {
  background: #e7f6f4;
  color: #1a6b62;
}
.dg-cockpit-kpi--inbox .dg-cockpit-kpi-icon {
  background: #fff1dc;
  color: #e0891a;
}
.dg-cockpit-kpi--free .dg-cockpit-kpi-icon {
  background: #f3eaff;
  color: #8b5cf6;
}
.dg-cockpit-kpi-copy {
  display: flex;
  min-width: 0;
  flex: 1;
  flex-direction: column;
  line-height: 1.15;
}
.dg-cockpit-kpi-copy strong {
  font-size: 1.45rem;
  font-weight: 750;
  letter-spacing: -0.03em;
  color: #172033;
}
.dg-cockpit-kpi-copy span {
  margin-top: 0.1rem;
  font-size: 0.82rem;
  font-weight: 650;
  color: #243044;
}
.dg-cockpit-kpi-copy small {
  margin-top: 0.15rem;
  font-size: 0.72rem;
  color: #80909a;
}
.dg-cockpit-kpi-chevron {
  width: 0.95rem;
  height: 0.95rem;
  flex: none;
  color: #b7c3cb;
}
.dg-cockpit-spark {
  display: flex;
  align-items: flex-end;
  gap: 0.18rem;
  height: 1.7rem;
  margin-right: 0.15rem;
}
.dg-cockpit-spark i {
  display: block;
  width: 0.28rem;
  border-radius: 999px;
  background: #7dcea5;
}
.dg-cockpit-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.25fr) minmax(16rem, 0.9fr) minmax(16rem, 0.9fr);
  gap: 0.75rem;
  align-items: start;
}
.dg-cockpit-stack,
.dg-cockpit-bottom {
  display: grid;
  gap: 0.75rem;
}
.dg-cockpit-bottom {
  grid-template-columns: minmax(0, 1.35fr) minmax(16rem, 0.9fr);
}
.dg-cockpit-card {
  padding: 0.9rem 1rem 1rem;
  border-radius: 1rem;
  background: #fff;
  border: 1px solid #e7eeea;
  box-shadow: 0 8px 22px rgba(24, 48, 36, 0.04);
}
.dg-cockpit-card-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  margin-bottom: 0.75rem;
}
.dg-cockpit-card-head h2 {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  margin: 0;
  font-size: 0.92rem;
  font-weight: 700;
  color: #1c2b3a;
}
.dg-cockpit-card-head h2 svg {
  width: 0.95rem;
  height: 0.95rem;
  color: #60717c;
}
.dg-cockpit-card-head h2 em {
  display: inline-grid;
  place-items: center;
  min-width: 1.15rem;
  height: 1.15rem;
  padding: 0 0.3rem;
  border-radius: 999px;
  background: #fff1e4;
  color: #d97706;
  font-style: normal;
  font-size: 0.68rem;
}
.dg-cockpit-card-head a,
.dg-cockpit-count {
  font-size: 0.75rem;
  font-weight: 650;
  color: #6d7f8a;
  text-decoration: none;
}
.dg-cockpit-card-head a:hover {
  color: #0e7a4b;
}
.dg-cockpit-empty {
  margin: 0.25rem 0 0.4rem;
  font-size: 0.8rem;
  color: #80909a;
}
.dg-cockpit-timeline {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  margin: 0;
  padding: 0;
  list-style: none;
}
.dg-cockpit-event {
  display: grid;
  grid-template-columns: 6.4rem minmax(0, 1fr) auto;
  align-items: center;
  gap: 0.55rem;
  min-height: 3.15rem;
  padding: 0.35rem 0;
}
.dg-cockpit-event time {
  position: relative;
  padding-left: 0.85rem;
  font-size: 0.72rem;
  font-weight: 650;
  color: #60717c;
}
.dg-cockpit-event time::before {
  content: '';
  position: absolute;
  left: 0;
  top: 0.35rem;
  width: 0.45rem;
  height: 0.45rem;
  border-radius: 50%;
  background: #1aa05a;
  box-shadow: 0 0 0 3px #e7f8ee;
}
.dg-cockpit-event--reunion time::before {
  background: #3b82f6;
  box-shadow: 0 0 0 3px #e8f1ff;
}
.dg-cockpit-event--mission time::before {
  background: #f59e0b;
  box-shadow: 0 0 0 3px #fff4e0;
}
.dg-cockpit-event--free time::before {
  background: #c5d0d6;
  box-shadow: 0 0 0 3px #f2f5f6;
}
.dg-cockpit-event-body {
  min-width: 0;
}
.dg-cockpit-event-body p {
  margin: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 0.84rem;
  font-weight: 700;
  color: #1c2b3a;
}
.dg-cockpit-kind {
  font-weight: 750;
}
.dg-cockpit-event-body small {
  display: block;
  margin-top: 0.12rem;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 0.72rem;
  color: #80909a;
}
.dg-cockpit-place,
.dg-cockpit-plan-mini {
  display: inline-flex;
  align-items: center;
  gap: 0.28rem;
  max-width: 9.5rem;
  min-height: 1.7rem;
  padding: 0 0.55rem;
  border-radius: 999px;
  font-size: 0.7rem;
  font-weight: 650;
  text-decoration: none;
}
.dg-cockpit-place {
  background: #f4f7f8;
  color: #4d6270;
}
.dg-cockpit-place span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.dg-cockpit-place svg,
.dg-cockpit-plan-mini svg {
  width: 0.75rem;
  height: 0.75rem;
  flex: none;
}
.dg-cockpit-plan-mini {
  border: 1px solid #d7e4fb;
  background: #f5f9ff;
  color: #3b82f6;
}
.dg-cockpit-attention,
.dg-cockpit-upcoming,
.dg-cockpit-contacts {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  margin: 0;
  padding: 0;
  list-style: none;
}
.dg-cockpit-attn,
.dg-cockpit-upcoming a,
.dg-cockpit-contacts a {
  display: flex;
  align-items: center;
  gap: 0.65rem;
  min-height: 2.7rem;
  text-decoration: none;
  color: inherit;
}
.dg-cockpit-attn-icon {
  display: grid;
  place-items: center;
  width: 2rem;
  height: 2rem;
  flex: none;
  border-radius: 0.65rem;
}
.dg-cockpit-attn-icon svg {
  width: 0.95rem;
  height: 0.95rem;
}
.dg-cockpit-attn--mail .dg-cockpit-attn-icon {
  background: #ffe8e6;
  color: #e15b55;
}
.dg-cockpit-attn--check .dg-cockpit-attn-icon {
  background: #e7f8ee;
  color: #14914d;
}
.dg-cockpit-attn--reunion .dg-cockpit-attn-icon {
  background: #fff1dc;
  color: #e0891a;
}
.dg-cockpit-attn--mission .dg-cockpit-attn-icon {
  background: #e7f8ee;
  color: #14914d;
}
.dg-cockpit-attn strong,
.dg-cockpit-upcoming strong,
.dg-cockpit-contacts strong {
  display: block;
  font-size: 0.8rem;
  font-weight: 700;
  color: #1c2b3a;
}
.dg-cockpit-attn small,
.dg-cockpit-upcoming small,
.dg-cockpit-contacts small {
  display: block;
  margin-top: 0.08rem;
  font-size: 0.7rem;
  color: #80909a;
}
.dg-cockpit-up-date {
  display: grid;
  place-items: center;
  width: 2.55rem;
  height: 2.55rem;
  flex: none;
  border-radius: 0.7rem;
  background: #f4f7f6;
}
.dg-cockpit-up-date strong {
  font-size: 0.82rem;
  line-height: 1;
}
.dg-cockpit-up-date small {
  margin-top: 0.12rem;
  font-size: 0.58rem;
  font-weight: 750;
  letter-spacing: 0.04em;
  color: #80909a;
}
.dg-cockpit-bars {
  display: flex;
  align-items: flex-end;
  gap: 0.35rem;
  height: 7.2rem;
  padding-top: 0.25rem;
}
.dg-cockpit-bar-col {
  display: flex;
  flex: 1;
  flex-direction: column;
  align-items: center;
  gap: 0.35rem;
  height: 100%;
  justify-content: flex-end;
}
.dg-cockpit-bar {
  display: flex;
  width: 0.72rem;
  flex-direction: column-reverse;
  overflow: hidden;
  border-radius: 999px;
  background: #eef2f3;
}
.dg-cockpit-bar-seg {
  display: block;
  width: 100%;
  min-height: 0.2rem;
}
.dg-cockpit-bar-seg--rdv { background: #3dbe73; }
.dg-cockpit-bar-seg--reunion { background: #5aa2f5; }
.dg-cockpit-bar-seg--mission { background: #f0a23a; }
.dg-cockpit-bar-seg--free { background: #d5dee3; }
.dg-cockpit-bar-seg--empty { background: #e7eef1; min-height: 0.45rem; }
.dg-cockpit-bar-label {
  min-height: 0.8rem;
  font-size: 0.62rem;
  color: #8b9aa3;
}
.dg-cockpit-legend,
.dg-cockpit-room-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 0.45rem 0.75rem;
  margin: 0.7rem 0 0;
  padding: 0;
  list-style: none;
}
.dg-cockpit-legend li,
.dg-cockpit-room-legend li {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  font-size: 0.7rem;
  color: #60717c;
}
.dg-cockpit-legend i,
.dg-cockpit-room-legend i {
  width: 0.45rem;
  height: 0.45rem;
  border-radius: 50%;
}
.dg-cockpit-legend .is-rdv { background: #3dbe73; }
.dg-cockpit-legend .is-reunion { background: #5aa2f5; }
.dg-cockpit-legend .is-mission { background: #f0a23a; }
.dg-cockpit-legend .is-free { background: #d5dee3; }
.dg-cockpit-room {
  display: flex;
  align-items: center;
  gap: 1.1rem;
}
.dg-cockpit-donut {
  display: grid;
  place-items: center;
  width: 7.1rem;
  height: 7.1rem;
  flex: none;
  border-radius: 50%;
}
.dg-cockpit-donut span {
  display: flex;
  width: 4.55rem;
  height: 4.55rem;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: #fff;
}
.dg-cockpit-donut strong {
  font-size: 1.35rem;
  line-height: 1;
  color: #172033;
}
.dg-cockpit-donut small {
  margin-top: 0.1rem;
  font-size: 0.62rem;
  color: #80909a;
}
.dg-cockpit-room-legend {
  flex-direction: column;
  gap: 0.45rem;
}
.dg-cockpit-room-legend strong {
  min-width: 0.7rem;
  color: #1c2b3a;
}
.dg-cockpit-room-name {
  margin: 0.65rem 0 0;
  font-size: 0.72rem;
  color: #80909a;
}
.dg-cockpit-shortcuts {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.65rem;
}
.dg-cockpit-shortcut {
  display: flex;
  min-height: 4.6rem;
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
  gap: 0.45rem;
  padding: 0.75rem 0.8rem;
  border-radius: 0.9rem;
  font-size: 0.78rem;
  font-weight: 700;
  text-decoration: none;
}
.dg-cockpit-shortcut svg {
  width: 1.05rem;
  height: 1.05rem;
}
.dg-cockpit-shortcut--rdv {
  background: #eefbf3;
  color: #128a4e;
}
.dg-cockpit-shortcut--reunion,
.dg-cockpit-shortcut--mail {
  background: #fff1f0;
  color: #c04545;
}
.dg-cockpit-shortcut--mission {
  background: #fff6ea;
  color: #e0891a;
}
.dg-cockpit-shortcut--room {
  background: #f6f1ff;
  color: #8b5cf6;
}
.dg-cockpit-avatar {
  display: grid;
  place-items: center;
  width: 2.35rem;
  height: 2.35rem;
  flex: none;
  border-radius: 50%;
  font-size: 0.68rem;
  font-weight: 750;
  color: #fff;
}
.dg-cockpit-avatar--0 { background: #3b82f6; }
.dg-cockpit-avatar--1 { background: #8b5cf6; }
.dg-cockpit-avatar--2 { background: #14b8a6; }
.dg-cockpit-avatar--3 { background: #f59e0b; }
.dg-cockpit-contacts {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.55rem 0.75rem;
}
@media (max-width: 1180px) {
  .dg-cockpit-kpis,
  .dg-cockpit-grid,
  .dg-cockpit-bottom,
  .dg-cockpit-shortcuts {
    grid-template-columns: 1fr 1fr;
  }
}
@media (max-width: 760px) {
  .dg-cockpit-kpis,
  .dg-cockpit-grid,
  .dg-cockpit-bottom,
  .dg-cockpit-shortcuts,
  .dg-cockpit-contacts,
  .dg-cockpit-event {
    grid-template-columns: 1fr;
  }
  .dg-cockpit-hello {
    font-size: 1.35rem;
  }
}

.dg-cockpit {
  gap: 0.55rem;
}
.dg-cockpit-hello {
  font-size: 1.28rem;
}
.dg-cockpit-lead {
  font-size: 0.75rem;
}
.dg-cockpit-date,
.dg-cockpit-fiche,
.dg-cockpit-plan {
  min-height: 1.9rem;
  font-size: 0.75rem;
}
.dg-cockpit-kpis,
.dg-cockpit-grid,
.dg-cockpit-bottom {
  gap: 0.5rem;
}
.dg-cockpit-grid {
  align-items: stretch;
}
.dg-cockpit.dg-cockpit--simple .dg-cockpit-grid {
  grid-template-columns: minmax(0, 1.5fr) minmax(14rem, 0.62fr);
}
.dg-frise {
  position: relative;
}
.dg-frise-axis {
  position: relative;
  height: 1.15rem;
}
.dg-frise-axis span {
  position: absolute;
  top: 0;
  width: 1px;
  height: 0.28rem;
  margin-top: 0.85rem;
  background: #d5e0da;
  transform: translateX(-50%);
}
.dg-frise-axis span.is-label {
  width: auto;
  height: auto;
  margin-top: 0;
  background: none;
  color: #5d6e78;
  font-size: 0.68rem;
  font-weight: 650;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.01em;
  transform: translateX(-50%);
}
.dg-frise-axis span.is-label::after {
  content: '';
  position: absolute;
  left: 50%;
  bottom: -0.32rem;
  width: 1px;
  height: 0.32rem;
  background: #b7c6be;
  transform: translateX(-50%);
}
.dg-frise-board {
  position: relative;
  border-radius: 0.75rem;
  background-color: #f4f7f5;
  background-image: linear-gradient(90deg, transparent calc(100% - 1px), rgba(20, 40, 30, 0.07) calc(100% - 1px));
  background-repeat: repeat-x;
}
.dg-lane {
  display: grid;
  grid-template-columns: 4.25rem minmax(0, 1fr);
  align-items: center;
  column-gap: 0.65rem;
  margin-top: 0.28rem;
}
.dg-lane--ruler {
  align-items: end;
  margin-top: 0;
  margin-bottom: 0.15rem;
}
.dg-lane--agenda .dg-lane-track { background: #f3faf6; border-color: #d7ebe0; }
.dg-lane--salle .dg-lane-track { background: #fbf7f1; border-color: #eadfce; }
.dg-lane-name {
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #7b8c86;
}
.dg-lane-track {
  position: relative;
  border: 1px solid #e4ece7;
  border-radius: 0.55rem;
  background: #f7faf8;
  overflow: hidden;
}
.dg-hour-line {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 1px;
  background: rgba(20, 40, 30, 0.06);
  pointer-events: none;
}
.dg-frise-block {
  position: absolute;
  z-index: 1;
  display: flex;
  align-items: center;
  gap: 0.32rem;
  height: 1.28rem;
  padding: 0 0.32rem;
  border-radius: 0.32rem;
  color: #fff;
  font-size: 0.68rem;
  font-weight: 650;
  letter-spacing: 0.01em;
  text-decoration: none;
  overflow: hidden;
  box-shadow: 0 1px 2px rgba(16, 36, 28, 0.16);
}
.dg-frise-block em {
  display: grid;
  place-items: center;
  min-width: 0.9rem;
  height: 0.9rem;
  padding: 0 0.12rem;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.2);
  font-style: normal;
  font-size: 0.6rem;
  font-weight: 750;
  flex: none;
}
.dg-frise-block span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.dg-frise-block--presentiel { background: #0f7a49; }
.dg-frise-block--ligne { background: #1d6fbf; }
.dg-frise-block--salle { background: #b86e14; }
.dg-frise-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 0.85rem 1.15rem;
  margin: 0.55rem 0 0 4.9rem;
  padding: 0;
  list-style: none;
}
.dg-frise-legend li {
  display: inline-flex;
  align-items: center;
  gap: 0.38rem;
  color: #5d6e78;
  font-size: 0.72rem;
  font-weight: 650;
}
.dg-frise-legend i {
  width: 0.7rem;
  height: 0.45rem;
  border-radius: 0.15rem;
}
.dg-frise-legend .is-presentiel { background: #0f7a49; }
.dg-frise-legend .is-ligne { background: #1d6fbf; }
.dg-frise-legend .is-salle { background: #b86e14; }
.dg-day-num--presentiel { color: #0f7a49; }
.dg-day-num--ligne { color: #1d6fbf; }
.dg-day-num--salle { color: #b86e14; }
.dg-day-split {
  display: grid;
  grid-template-columns: minmax(0, 1.15fr) minmax(0, 0.85fr);
  gap: 0.85rem 1.25rem;
  margin-top: 0.9rem;
}
.dg-day-kicker {
  margin: 0 0 0.35rem;
  font-size: 0.68rem;
  font-weight: 750;
  letter-spacing: 0.06em;
