  color: #b86e00;
}
.ext-own-kpi--rejected .ext-own-kpi-icon {
  background: #fdecea;
  color: #d6453d;
}
.ext-own-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(15rem, 17.5rem);
  gap: 0.45rem;
  align-items: start;
}
.ext-own-side {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}
.ext-own-card {
  border: 1px solid #e3ebe6;
  border-radius: 0.6rem;
  background: #fff;
  padding: 0.5rem 0.6rem 0.55rem;
  box-shadow: 0 1px 2px rgba(16, 40, 32, 0.04);
}
.ext-own-card h2 {
  margin: 0;
  font-size: 0.8rem;
  font-weight: 700;
  color: #163028;
}
.ext-own-card-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  margin-bottom: 0.35rem;
}
.ext-own-more {
  font-size: 0.75rem;
  font-weight: 650;
  color: #0b7a45;
}
.ext-own-more:hover {
  text-decoration: underline;
}
.ext-own-empty,
.ext-own-empty-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.1rem;
  padding: 0.55rem 0.4rem 0.4rem;
  text-align: center;
  color: #8a978f;
}
.ext-own-empty p,
.ext-own-empty-card p {
  margin: 0.1rem 0 0;
  font-size: 0.75rem;
  font-weight: 650;
  color: #5c6b64;
}
.ext-own-empty small {
  max-width: 18rem;
  font-size: 0.66rem;
  line-height: 1.3;
}
.ext-own-empty-card a {
  margin-top: 0.35rem;
  font-size: 0.78rem;
  font-weight: 650;
  color: #0b7a45;
}
.ext-own-list {
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
  margin: 0;
  padding: 0;
  list-style: none;
}
.ext-own-list li {
  display: grid;
  grid-template-columns: 8.5rem minmax(0, 1fr) auto;
  gap: 0.65rem;
  align-items: center;
  padding: 0.65rem 0.7rem;
  border: 1px solid #eef3f0;
  border-radius: 0.7rem;
  background: #f8fbf9;
}
.ext-own-list time {
  display: flex;
  flex-direction: column;
  gap: 0.1rem;
  font-size: 0.68rem;
  color: #6b7a73;
}
.ext-own-list time strong {
  font-size: 0.78rem;
  color: #163028;
}
.ext-own-item-title {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 0.82rem;
  font-weight: 650;
  color: #163028;
}
.ext-own-status {
  display: inline-flex;
  align-items: center;
  padding: 0.15rem 0.45rem;
  border-radius: 999px;
  font-size: 0.68rem;
  font-weight: 700;
  background: #eef3f0;
  color: #5c6b64;
}
.ext-own-status--pending {
  background: #fff4e5;
  color: #9a5b0c;
}
.ext-own-status--approved {
  background: #e7f6ee;
  color: #0b7a45;
}
.ext-own-status--rejected {
  background: #fdecea;
  color: #d6453d;
}
.ext-own-links {
  display: flex;
  flex-direction: column;
  gap: 0.1rem;
  margin: 0.3rem 0 0;
  padding: 0;
  list-style: none;
}
.ext-own-links a {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.28rem 0.4rem;
  border-radius: 0.4rem;
  font-size: 0.74rem;
  font-weight: 600;
  color: #163028;
}
.ext-own-links a svg {
  width: 0.9rem;
  height: 0.9rem;
}
.ext-own-card .ext-plan-tips {
  gap: 0.18rem;
  margin: 0.35rem 0 0;
}
.ext-own-card .ext-plan-tips li {
  padding: 0.18rem 0.35rem;
  font-size: 0.7rem;
}
.ext-own-links a:hover {
  background: #f3faf6;
  color: #0b7a45;
}
.ext-own-agenda .ext-own-card + .ext-own-card {
  margin-top: 0;
}
.ext-own-agenda .ext-own-card h2 {
  margin-bottom: 0.7rem;
}
@media (max-width: 900px) {
  .ext-own-kpis,
  .ext-own-grid {
    grid-template-columns: 1fr 1fr;
  }
  .ext-own-grid {
    grid-template-columns: 1fr;
  }
}
@media (max-width: 640px) {
  .ext-own-kpis {
    grid-template-columns: 1fr;
  }
  .ext-own-list li {
    grid-template-columns: 1fr;
    gap: 0.25rem;
  }
}
